  _ = `Buton de pornire giroscop – Clic al padului stâng`,
  _ = `Giroscopul va fi pornit numai atunci când faci clic pe trackpadul stâng.`,
  _ = `Buton de pornire giroscop – Bumperul drept`,
  _ = `Giroscopul va fi pornit numai atunci când bumperul drept este apăsat.`,
  _ = `Buton de pornire giroscop – Bumperul stâng`,
  _ = `Giroscopul va fi pornit numai atunci când bumperul stâng este apăsat.`,
  _ = `Buton de pornire giroscop – Butonul de prindere drept`,
  _ = `Giroscopul va fi pornit numai atunci când butonul de prindere drept este apăsat.`,
  _ = `Buton de pornire giroscop – Butonul de prindere stâng`,
  _ = `Giroscopul va fi pornit numai atunci când butonul de prindere stâng este apăsat.`,
  _ = `Buton de pornire giroscop – Apăsare completă a triggerului stâng`,
