  _ = `Buton de pornire giroscop – Triunghi`,
  _ = `Giroscopul va fi pornit numai atunci când butonul Triunghi este apăsat.`,
  _ = `Buton de pornire giroscop – Clic al stickului stâng`,
  _ = `Giroscopul va fi pornit numai atunci când faci clic pe stickul stâng.`,
  _ = `Buton de pornire giroscop – Clic al stickului drept`,
  _ = `Giroscopul va fi pornit numai atunci când faci clic pe stickul drept.`,
  _ = `Buton de pornire giroscop – Clic al butonului Captură`,
  _ = `Giroscopul va fi pornit numai atunci când faci clic pe butonul Captură.`,
  _ = `Buton de pornire giroscop – Triggerul drept`,
