  _ = `Închide după activare`,
  _ = `În funcție de această setare, meniul poate să se închidă în mod automat după activarea unui element sau să rămână activ, permițând jucătorului să activeze elementul selectat de mai multe ori.`,
  _ = `Închide după activare – Pornit`,
  _ = `Când această setare este activată, meniul se va închide automat după activarea unei comenzi.`,
  _ = `Închide după activare – Oprit`,
  _ = `Când această setare este dezactivată, meniul va rămâne vizibil după activarea unei comenzi.`,
  _ = `Recentrează de fiecare dată`,
  _ = `Prin intermediul acestei opțiuni, meniul poate, atunci când este invocat, fie să rețină elementul selectat anterior, fie să reseteze selecția pentru a selecta elementul din poziția centrală.`,
  _ = `Recentrează de fiecare dată – Da`,
  _ = `Când această setare este activată, de fiecare dată când meniul este deschis, elementul selectat va fi resetat la comanda aflată în poziția centrală.`,
  _ = `Recentrează de fiecare dată – Nu`,
  _ = `Când această setare este dezactivată, meniul va reține comanda selectată la deschiderea sa anterioară.`,
  _ = `Derulare în buclă`,
  _ = `Atunci când meniul ajunge la finalul listei de comenzi, derularea poate fie să continue în buclă, fie să înceteze definitiv.`,
  _ = `Derulare în buclă – Pornită`,
  _ = `Când această setare este activată, derularea din meniu va continua în buclă atunci când derulezi până la finalul listei de comenzi.`,
  _ = `Derulare în buclă – Oprită`,
  _ = `Când această setare este dezactivată, meniul va înceta să se deruleze atunci când ajunge la finalul listei de comenzi.`,
