  _ = `Poți atribui comenzi acestui buton virtual.`,
  _ = `Meniu radial – Butonul 16`,
  _ = `Poți atribui comenzi acestui buton virtual.`,
  _ = `Meniu radial – Butonul 17`,
  _ = `Poți atribui comenzi acestui buton virtual.`,
  _ = `Meniu radial – Butonul 18`,
