  _ = `Poți atribui comenzi acestui buton virtual.`,
  _ = `Buton pentru meniul radial`,
  _ = `Poți atribui comenzi atunci când faci clic pe acest input. Acest lucru este util în special atunci când este combinat cu tipul de activare al meniului „Întotdeauna pornit”.`,
  _ = `Opacitatea meniului radial`,
  _ = `Glisorul determină gradul de transparență al meniului radial pe ecran.`,
  _ = `Dimensiunea meniului radial`,
  _ = `Glisorul determină dimensiunea pe ecran a meniului radial.`,
  _ = `Clic al butonului`,
  _ = `Aceasta va activa opțiunea din meniu atunci când butonul este apăsat.`,
  _ = `Eliberarea butonului`,
  _ = `Aceasta va activa opțiunea din meniu atunci când butonul este eliberat.`,
  _ = `Eliberarea atingerii`,
  _ = `Aceasta va activa opțiunea din meniu atunci când trackpadul nu mai este atins sau când butonul pentru modificarea de mod este eliberat. Pentru joystickuri, orice poziție din afara zonei moarte constituie o atingere.`,
  _ = `Întotdeauna`,
  _ = `Aceasta va activa opțiunea din meniu în mod continuu cât timp trackpadul sau stickul este atins. Pentru joystickuri, orice poziție din afara zonei moarte constituie o atingere.`,
  _ = `Afișează eticheta comenzii butonului – Activat`,
  _ = `Această setare va activa afișarea etichetei comenzii pe buton. Dacă este utilizată o pictogramă, această etichetă va fi afișată doar în colțul din stânga sus.`,
  _ = `Afișează eticheta comenzii butonului – Dezactivat`,
  _ = `Această setare va dezactiva afișarea etichetei comenzii pe buton și va afișa în schimb pictograma sau un buton gol.`,
  _ = `Trimite comanda din meniu atunci când trackpadul este apăsat.`,
